parameters.jsCode:
try {
    const body = $input.item.json.body || {};

    // 1. ПОЧТА КАЛЕНДАРЯ
    const targetCalendarEmail = "andcoestate@gmail.com"; 

    // 2. ИЗВЛЕКАЕМ ID (Поддерживает и TG ID, и Email)
    let rawId = body.system_client_identifier || body.contact_id || body.client_email || "";

    // Вырезаем фигурные скобки, если Dify прислал {{contact_id}} или {{email@mail.com}}
    let cleanContactId = String(rawId).replace(/[{}]/g, '').trim();

    // ПРЕДОХРАНИТЕЛЬ: Если Dify прислал тупо текст "contact_id" вместо значения
    if (cleanContactId === "contact_id" || cleanContactId === "") {
        throw new Error(`Dify не подставил переменную! В вебхук пришло: ${rawId}`);
    }

    // 3. ПРОВЕРКА ВРЕМЕНИ
    const startTime = body.start_time;
    const endTime = body.end_time;

    if (!startTime || !endTime) {
        throw new Error(`Dify обрезал время встречи! Данные вебхука: ${JSON.stringify(body)}`);
    }

    // 4. ДАННЫЕ О КЛИЕНТЕ
    const title = body.event_title || "Discovery Call";
    const pains = body.client_pain_points || "Не указано";
    const brief = body.company_brief || "Не указано";

    // 5. ОТДАЕМ ЧИСТЫЙ РЕЗУЛЬТАТ
    return {
        json: {
            calendar_id: targetCalendarEmail,
            contact_id: cleanContactId, // Тут будет "123456" ИЛИ "client@mail.com"
            start_time: startTime,
            end_time: endTime,
            event_title: title,
            client_pain_points: pains,
            company_brief: brief
        }
    };

} catch (error) {
    throw new Error(error.message);
}

try {
    const eventData = $("Create an event").first().json || {};

    let dbData = {};
    try {
        dbData = $("Execute a SQL query").first().json || {};
    } catch (e) {}

    const preData = $("Code in JavaScript").first().json || {};

    const meetLink = eventData.hangoutLink || "Ссылка будет в приглашении";

    if (eventData.id) {
        return {
            json: {
                status: "success",
                message: `Встреча создана. Ссылка на Meet: ${meetLink}.`,

                tg_report: {
                    meet_url: meetLink,
                    contact: preData.contact_id, // TG ID или Email
                    company_info: preData.company_brief, // Бриф о компании!
                    niche: dbData.company_niche || "Не найдено в БД",

                    // Берем свежие боли от ИИ, если нет - из базы
                    pains: (preData.client_pain_points && preData.client_pain_points !== "Не указано") 
                           ? preData.client_pain_points 
                           : (dbData.ai_pain_point || "Не найдено в БД"),

                    pitch: dbData.custom_pitch || "Не найдено в БД",
                    time: eventData.start?.dateTime || preData.start_time,
                    title: eventData.summary || preData.event_title || "Discovery Call"
                }
            }
        };
    } else {
        return { json: { status: "error", message: "Критическая ошибка Google Calendar." } };
    }
} catch (error) {
    return { json: { status: "error", message: "Ошибка отчета: " + error.message } };
}

